1	import type { FastifyPluginAsync } from 'fastify'
2	import { openDispute, resolveDispute } from '../../services/disputeService'
3	import type { DisputeResolution } from '../../domain/disputes/types'
4	
5	const disputesRoutes: FastifyPluginAsync = async (fastify) => {
6	  fastify.post<{
7	    Params: { claimId: string; lineItemId: string }
8	    Body: { memberReason: string }
9	  }>('/claims/:claimId/line-items/:lineItemId/dispute', async (request, reply) => {
10	    const dispute = await openDispute(request.params.lineItemId, request.body.memberReason)
11	    return reply.status(201).send(dispute)
12	  })
13	
14	  fastify.post<{
15	    Params: { id: string }
16	    Body: { resolution: DisputeResolution; resolverNote: string }
17	  }>('/disputes/:id/resolve', async (request, reply) => {
18	    const dispute = await resolveDispute(
19	      request.params.id,
20	      request.body.resolution,
21	      request.body.resolverNote
22	    )
23	    return reply.send(dispute)
24	  })
25	}
26	
27	export default disputesRoutes
